// Zoom is independent of game coordinates; SVG screen matrices handle clicks at any scale.
export function installMapView(){const board=document.querySelector('.boardwrap'),viewport=document.createElement('div');viewport.className='mapViewport';board.before(viewport);viewport.append(board);const bar=document.createElement('div');bar.className='mapZoom';bar.innerHTML='<button id="zoomOut" aria-label="缩小地图">−</button><output id="zoomValue">100%</output><button id="zoomIn" aria-label="放大地图">＋</button><button id="zoomFit">适配宽度</button><span>25%–300% · 放大后滚动查看</span>';viewport.before(bar);let zoom=1;const update=()=>{board.style.width=(zoom*100)+'%';board.style.marginInline=zoom<1?'auto':'0';document.getElementById('zoomValue').value=Math.round(zoom*100)+'%';document.getElementById('zoomOut').disabled=zoom<=.25;document.getElementById('zoomIn').disabled=zoom>=3;};document.getElementById('zoomOut').onclick=()=>{zoom=Math.max(.25,zoom-.25);update();};document.getElementById('zoomIn').onclick=()=>{zoom=Math.min(3,zoom+.25);update();};document.getElementById('zoomFit').onclick=()=>{zoom=1;update();};update();}
